// The pylon models a course can use. Every one is GENERATED by the app (core/pylon: an OBJ8 tube and
// a banded PNG), so nothing from Laminar, IPACS or any other artist travels into a pack, and every
// height and radius is exact rather than measured off someone's model (docs/DESIGN.md D5).
//
// The ids are the ones Pylon Racer (Aerofly) stores in course files, so a .pylonrace made there opens
// here with the same look: "red" is still red, "rodeo-25" is still 25 m. Rodeo's and krzysk1's
// models themselves did not come across; these are their stand-ins. Ids never change.
import type { GateType, Rules } from "../course/course";
import type { Rgb } from "../pylon/texture";

export interface PylonModel {
  id: string;
  label: string;
  /** Map color (token-independent: it describes the model's paint). */
  color: string;
  /** Paint bands from the foot to the top. */
  bands: readonly Rgb[];
  /** Exact height of the generated model, m. */
  heightM: number;
  baseRadiusM: number;
  topRadiusM: number;
}

const WHITE: Rgb = [245, 245, 245];
const RED: Rgb = [226, 59, 59];
const GREEN: Rgb = [39, 168, 68];
const BLUE: Rgb = [47, 111, 214];
const AMBER: Rgb = [245, 158, 11];
const YELLOW: Rgb = [234, 179, 8];
const ORANGE: Rgb = [234, 88, 12];
const CYAN: Rgb = [8, 145, 178];
const TEAL: Rgb = [14, 116, 144];

/** Color at the foot and the top, white between: reads as a pylon, and the same upside down. */
const striped = (c: Rgb): Rgb[] => [c, WHITE, c, WHITE, c];

export const PYLONS: readonly PylonModel[] = [
  { id: "red", label: "Red 15 m", color: "#e23b3b", bands: striped(RED), heightM: 15, baseRadiusM: 1.2, topRadiusM: 0.5 },
  { id: "green", label: "Green 15 m", color: "#27a844", bands: striped(GREEN), heightM: 15, baseRadiusM: 1.2, topRadiusM: 0.5 },
  { id: "blue", label: "Blue 15 m", color: "#2f6fd6", bands: striped(BLUE), heightM: 15, baseRadiusM: 1.2, topRadiusM: 0.5 },
  { id: "home", label: "Home (tall) 25 m", color: "#f59e0b", bands: striped(AMBER), heightM: 25, baseRadiusM: 2, topRadiusM: 0.8 },
  { id: "home2", label: "Home 2, 18 m", color: "#eab308", bands: striped(YELLOW), heightM: 18, baseRadiusM: 1.5, topRadiusM: 0.6 },
  { id: "rgb", label: "RGB 15 m", color: "#8b5cf6", bands: [RED, WHITE, GREEN, WHITE, BLUE], heightM: 15, baseRadiusM: 1.2, topRadiusM: 0.5 },
  { id: "rb", label: "Red-Blue 15 m", color: "#c0399b", bands: [RED, WHITE, BLUE, WHITE, RED], heightM: 15, baseRadiusM: 1.2, topRadiusM: 0.5 },
  // The sizes of Rodeo's air-race pylons in Pylon Racer (bounding boxes 2.10 × 15.18, 4 × 18, 5 × 25 m).
  { id: "rodeo-reno", label: "Reno 15 m", color: "#ea580c", bands: striped(ORANGE), heightM: 15.18, baseRadiusM: 1.05, topRadiusM: 0.45 },
  { id: "rodeo-18", label: "Air Race 18 m", color: "#0891b2", bands: striped(CYAN), heightM: 18, baseRadiusM: 2, topRadiusM: 0.8 },
  { id: "rodeo-25", label: "Air Race 25 m", color: "#0e7490", bands: striped(TEAL), heightM: 25, baseRadiusM: 2.5, topRadiusM: 1 },
];

export const DEFAULT_PYLON: Record<GateType, string> = {
  start: "green",
  finish: "home",
  gate: "red",
  level: "blue",
  knife: "rgb",
  inverted: "rb",
  turn: "home2",
};

/**
 * How big a course's pylons are, all of them at once (DESIGN D15). In a sim a 15 m pylon is hard to
 * pick out from far away, so a course can ask for every model twice as big: twice as tall and as
 * wide, the same paint. Ids never change: a course file stores them.
 */
export const PYLON_SIZES = ["standard", "tall"] as const;
export type PylonSize = (typeof PYLON_SIZES)[number];

export const PYLON_SCALE: Record<PylonSize, number> = { standard: 1, tall: 2 };

type GateRef = { type: GateType; pylon: string | null };

/** The model a gate uses: its own choice if it is a known id, else the default for its type. */
export function pylonFor(gate: GateRef): PylonModel {
  const byId = (id: string | null): PylonModel | undefined => PYLONS.find((p) => p.id === id);
  return byId(gate.pylon) ?? byId(DEFAULT_PYLON[gate.type]) ?? PYLONS[0]!;
}

/** A model at a course's pylon size: every dimension scaled, the paint unchanged. */
export function sizedPylon(model: PylonModel, size: PylonSize): PylonModel {
  const k = PYLON_SCALE[size];
  if (k === 1) return model;
  return { ...model, heightM: model.heightM * k, baseRadiusM: model.baseRadiusM * k, topRadiusM: model.topRadiusM * k };
}

/** How tall a gate's pylons are for the pylon-hit rule. Every generated model knows its height, so
 *  the course-wide `pylonHeightM` (kept for Aerofly's courses, whose models did not) is never used. */
export function pylonHeightFor(gate: GateRef, rules: Pick<Rules, "pylonHeightM" | "pylonSize">): number {
  return sizedPylon(pylonFor(gate), rules.pylonSize).heightM;
}

/** How close to a gate pylon's center counts as a hit. `pylonHitRadiusM` is set for the standard
 *  models; a bigger pylon widens it by as much as its foot widened, so the clearance it asks for stays
 *  the same and a hit is never inside the pylon (the Air Race 25 m is 5 m wide at the foot when tall). */
export function pylonHitRadiusFor(gate: GateRef, rules: Pick<Rules, "pylonHitRadiusM" | "pylonSize">): number {
  const model = pylonFor(gate);
  return rules.pylonHitRadiusM + sizedPylon(model, rules.pylonSize).baseRadiusM - model.baseRadiusM;
}

/** The model's name for a picker: as it is at the standard size, with its real height when bigger. */
export function pylonLabel(model: PylonModel, size: PylonSize): string {
  return size === "standard" ? model.label : `${model.label} → ${Math.round(sizedPylon(model, size).heightM)} m`;
}
